sys_variable_value.value:
(function execute(inputs, outputs) {

    var gr = inputs.approver;

    gs.info("Table: " + gr.getTableName());
    gs.info("Sys ID: " + gr.getValue("sys_id"));
    gs.info("Approver User: " + gr.getValue("approver_user"));
    gs.info("Approver User Display: " + gr.getDisplayValue("approver_user"));

    outputs.approver = gr;

})(inputs, outputs);

